const ARCHIVE_WHITESPACE = /^[\u0009\u000D\u0020]*$/;

function parseArchiveRecord(text, line) {
  if (ARCHIVE_WHITESPACE.test(text)) {
    return { empty: true };
  }

  try {
    return { empty: false, value: JSON.parse(text) };
  } catch (cause) {
    const error = new SyntaxError(
      cause instanceof Error ? cause.message : "Invalid JSON record"
    );
    error.code = "INVALID_RECORD";
    error.line = line;
    throw error;
  }
}

async function* readArchive(chunks) {
  let iterator;
  let reachedEOF = false;
  let failed = false;

  try {
    iterator = chunks[Symbol.asyncIterator]();

    const decoder = new TextDecoder("utf-8");
    let lineText = "";
    let lineNumber = 1;
    let hasUnterminatedLine = false;

    while (true) {
      const result = await iterator.next();

      if (result.done) {
        reachedEOF = true;
        lineText += decoder.decode();

        if (hasUnterminatedLine) {
          const parsed = parseArchiveRecord(lineText, lineNumber);
          if (!parsed.empty) {
            yield parsed.value;
          }
        }

        return;
      }

      const chunk = result.value;
      let segmentStart = 0;

      for (let index = 0; index < chunk.length; index += 1) {
        if (chunk[index] !== 0x0a) {
          continue;
        }

        if (index > segmentStart) {
          lineText += decoder.decode(
            chunk.subarray(segmentStart, index),
            { stream: true }
          );
        }

        lineText += decoder.decode();

        if (lineText.endsWith("\r")) {
          lineText = lineText.slice(0, -1);
        }

        const currentLine = lineNumber;
        lineNumber += 1;
        const parsed = parseArchiveRecord(lineText, currentLine);

        lineText = "";
        hasUnterminatedLine = false;
        segmentStart = index + 1;

        if (!parsed.empty) {
          yield parsed.value;
        }
      }

      if (segmentStart < chunk.length) {
        lineText += decoder.decode(
          chunk.subarray(segmentStart),
          { stream: true }
        );
        hasUnterminatedLine = true;
      }
    }
  } catch (error) {
    failed = true;
    throw error;
  } finally {
    if (iterator !== undefined && !reachedEOF) {
      try {
        const close = iterator.return;
        if (typeof close === "function") {
          await close.call(iterator);
        }
      } catch (closeError) {
        if (!failed) {
          throw closeError;
        }
      }
    }
  }
}
